function sheetHasDataRows(
  workbook: XLSX.WorkBook,
  candidates: string[],
  excludedNames: string[] = []
): boolean {
  const sheetName = workbook.SheetNames.find(
    (name) =>
      candidates.some((candidate) => name.includes(candidate)) &&
      !excludedNames.some((excluded) => name.includes(excluded))
  );
  if (!sheetName) return false;
  return rows(workbook, sheetName)
    .slice(1)
    .some((row) => row.some((value) => normalizeText(value)));
}

function parseStaff(
  workbook: XLSX.WorkBook,
  leaveTypes: readonly LeaveType[],
  warnings: string[],
  restoreErrors: string[]
): Staff[] | undefined {
  const sheetName = findSheet(workbook, ["人员信息", "员工信息"]);
  if (!sheetName) return undefined;
  const data = rows(workbook, sheetName);
  const header = data[0] ?? [];
  const idIndex = headerIndex(header, ["编号", "员工号"], 0);
  const nameIndex = headerIndex(header, ["姓名"], 1);
  const nightIndex = headerIndex(header, ["夜班"], 2);
  const statusIndex = headerIndex(header, ["状态"], 3);
  const leaveIdIndex = header.findIndex(
    (cell) => normalizeText(cell) === "休假类别编号"
  );
  const remarkIndex = headerIndex(header, ["备注"], 4);
  const staffTypeIndex = headerIndex(
    header,
    ["人员类型", "人员分类", "类型"],
    5
  );
  const cxPreflightIndex = headerIndex(
    header,
    ["CX航前资质", "CX航前", "航前资质"],
    6
  );
  const dutyIndex = header.findIndex((cell) =>
    ["值班资质", "值班人员资质"].some((candidate) =>
      normalizeText(cell).includes(candidate)
    )
  );
  const standbyIndex = header.findIndex((cell) =>
    ["备勤资质", "备勤人员资质"].some((candidate) =>
      normalizeText(cell).includes(candidate)
    )
  );
  const teamLeaderIndex = header.findIndex((cell) =>
    ["是否为分队长", "分队长"].some((candidate) =>
      normalizeText(cell).includes(candidate)
    )
  );
  return data.slice(1).flatMap((row, rowIndex) => {
    if (row.every((value) => !normalizeText(value))) return [];
    const id = normalizeText(row[idIndex]);
    const name = normalizeText(row[nameIndex]);
    if (!id || !name) {
      restoreErrors.push(
        `人员信息第${rowIndex + 2}行：缺少人员编号或姓名，不能完整恢复`
      );
      return [];
    }
    const rawStatus = normalizeText(row[statusIndex]);
    const leaveId = leaveIdIndex >= 0 ? normalizeText(row[leaveIdIndex]) : "";
    const leaveType = leaveId
      ? leaveTypes.find((type) => type.id === leaveId)
      : leaveTypes.find((type) => type.name === rawStatus);
    const builtin = BUILTIN_STAFF_STATUSES.find(
      (status) => status === rawStatus
    );
    const status: Staff["status"] =
      leaveId || leaveType
        ? "休假"
        : (builtin ?? (rawStatus ? "休假" : "正常"));
    if ((leaveId && !leaveType) || (rawStatus && !builtin && !leaveType))
      warnings.push(
        `人员信息第${rowIndex + 2}行：无法识别休假类别“${rawStatus || leaveId}”，保留人员并按休假处理，请核对类别`
      );
    const staffType: Staff["staffType"] = normalizeText(
      row[staffTypeIndex]
    ).includes("行政")
      ? "行政支援"
      : "常规";
    return [
      {
        id,
        name,
        staffType,
        teamLeader:
          staffType === "常规" &&
          teamLeaderIndex >= 0 &&
          ["是", "有", "true", "1"].includes(
            normalizeText(row[teamLeaderIndex]).toLowerCase()
          ),
        cxPreflightQualified:
          staffType === "常规" &&
          ["是", "有", "true", "1"].includes(
            normalizeText(row[cxPreflightIndex]).toLowerCase()
          ),
        dutyQualified:
          staffType === "常规" &&
          (dutyIndex < 0 ||
            !["否", "无", "false", "0"].includes(
              normalizeText(row[dutyIndex]).toLowerCase()
            )),
        standbyQualified:
          staffType === "常规" &&
          (standbyIndex < 0 ||
            !["否", "无", "false", "0"].includes(
              normalizeText(row[standbyIndex]).toLowerCase()
            )),
        nightShift: !["否", "不可以", "false", "0"].includes(
          normalizeText(row[nightIndex]).toLowerCase()
        ),
        status,
        ...(leaveType || leaveId
          ? { leaveTypeId: leaveType?.id ?? leaveId }
          : {}),
        remark: normalizeText(row[remarkIndex]),
      },
    ];
  });
}

function parseFlightPositions(value: unknown): string[] {
  return splitPositionList(value).map(normalizePosition).filter(Boolean);
}

function recordFlightHeaderErrors(
  header: unknown[],
  sheetName: string,
  errors: string[]
): void {
  if (
    ["航班号", "开始时间", "结束时间"].some(
      (name) => headerIndex(header, [name], -1) < 0
    )
  )
    errors.push(
      `${sheetName}表头需包含航班号、开始时间和结束时间；不能完整恢复`
    );
}

function acceptFlightRow(
  sheetName: string,
  rowNumber: number,
  flightNo: string,
  startTime: string,
  endTime: string,
  seen: Set<string>,
  errors: string[],
  allowEmptyTime = false
): boolean {
  if (!flightNo || ((!startTime || !endTime) && !allowEmptyTime)) {
    errors.push(
      `${sheetName}第${rowNumber}行：航班号或开始、结束时间缺失/无效；不能完整恢复`
    );
    return false;
  }
  if (seen.has(flightNo))
    errors.push(`${sheetName}第${rowNumber}行：航班号重复；不能完整恢复`);
  seen.add(flightNo);
  return true;
}

function parseFlights(
  workbook: XLSX.WorkBook,
  errors: string[]
): Flight[] | undefined {
  const sheetName = workbook.SheetNames.find(
    (name) => name.includes("航班计划") && !name.includes("每周航班计划")
  );
  if (!sheetName) return undefined;
  const data = rows(workbook, sheetName);
  const header = data[0] ?? [];
  recordFlightHeaderErrors(header, sheetName, errors);
  const flightIndex = headerIndex(header, ["航班号"], 0);
  const startIndex = headerIndex(header, ["开始时间"], 1);
  const endIndex = headerIndex(header, ["结束时间"], 2);
  const passengerIndex = headerIndex(
    header,
    ["预定人数", "旅客人数", "运力人数"],
    3
  );
  const positionIndex = headerIndex(header, ["涉及岗位", "岗位"], 4);
  const remarkIndex = headerIndex(header, ["备注"], 5);
  const seen = new Set<string>();
  return data.slice(1).flatMap((row, index) => {
    if (row.every((value) => !normalizeText(value))) return [];
    const flightNo = normalizeText(row[flightIndex]).toUpperCase();
    const startTime = normalizeTime(normalizeText(row[startIndex]));
    const endTime = normalizeTime(normalizeText(row[endIndex]));
    if (
      !acceptFlightRow(
        sheetName,
        index + 2,
        flightNo,
        startTime,
        endTime,
        seen,
        errors
      )
    )
      return [];
    return [
      {
        id: createId("flight"),
        flightNo,
        startTime,
        endTime,
        bookedPassengers: Number(row[passengerIndex]) || 0,
        positions: parseFlightPositions(row[positionIndex]),
        remark: normalizeText(row[remarkIndex]),
      },
    ];
  });
}

function parseTemplates(
  workbook: XLSX.WorkBook,
  errors: string[]
): FlightTemplate[] | undefined {
  const sheetName = findSheet(workbook, ["航班配置", "航班模板"]);
  if (!sheetName) return undefined;
  const data = rows(workbook, sheetName);
  const header = data[0] ?? [];
  recordFlightHeaderErrors(header, sheetName, errors);
  const flightIndex = headerIndex(header, ["航班号"], 0);
  const startIndex = headerIndex(header, ["开始时间"], 1);
  const endIndex = headerIndex(header, ["结束时间"], 2);
  const positionIndex = headerIndex(header, ["涉及岗位", "岗位"], 3);
  const remarkIndex = headerIndex(header, ["备注"], 4);
  const seen = new Set<string>();
  return data.slice(1).flatMap((row, index) => {
    if (row.every((value) => !normalizeText(value))) return [];
    const flightNo = normalizeText(row[flightIndex]).toUpperCase();
    const startTime = normalizeTime(normalizeText(row[startIndex]));
    const endTime = normalizeTime(normalizeText(row[endIndex]));
    if (
      !acceptFlightRow(
        sheetName,
        index + 2,
        flightNo,
        startTime,
        endTime,
        seen,
        errors,
        !normalizeText(row[startIndex]) && !normalizeText(row[endIndex])
      )
    )
      return [];
    return [
      {
        id: createId("template"),
        flightNo,
        startTime,
        endTime,
        positions: parseFlightPositions(row[positionIndex]),
        remark: normalizeText(row[remarkIndex]),
      },
    ];
  });
}

function parseWeeklyFlightPlans(
  workbook: XLSX.WorkBook
):
  | { status: "valid"; plans: WeeklyFlightPlanEntry[] }
  | { status: "invalid"; warning: string }
  | undefined {
  const sheetName = findSheet(workbook, ["每周航班计划"]);
  if (!sheetName) return undefined;
  const data = rows(workbook, sheetName);
  const header = data[0] ?? [];
  const weekdayIndex = headerIndex(header, ["星期"], -1);
  const flightIndex = headerIndex(header, ["航班号"], -1);
  if (weekdayIndex < 0 || flightIndex < 0)
    return {
      status: "invalid",
      warning: "每周航班计划表头需包含“星期”和“航班号”，现有计划保留",
    };
  const dataRows = data
    .slice(1)
    .map((row, index) => ({ row, excelRow: index + 2 }))
    .filter(({ row }) => row.some((cell) => normalizeText(cell) !== ""));
  if (!dataRows.length)
    return { status: "valid", plans: createEmptyWeeklyFlightPlans() };
  let plans = createEmptyWeeklyFlightPlans();
  const seenWeekdays = new Set<number>();
  const weekdayByLabel = new Map<string, number>([
    ["星期一", 1],
    ["周一", 1],
    ["星期二", 2],
    ["周二", 2],
    ["星期三", 3],
    ["周三", 3],
    ["星期四", 4],
    ["周四", 4],
    ["星期五", 5],
    ["周五", 5],
    ["星期六", 6],
    ["周六", 6],
    ["星期日", 7],
    ["星期天", 7],
    ["周日", 7],
    ["周天", 7],
  ]);
  for (const { row, excelRow } of dataRows) {
    const rawWeekday = normalizeText(row[weekdayIndex]);
    const numericWeekday = Number(rawWeekday);
    const weekday =
      weekdayByLabel.get(rawWeekday) ??
      (Number.isInteger(numericWeekday) &&
      numericWeekday >= 1 &&
      numericWeekday <= 7
        ? numericWeekday
        : undefined);
    if (!weekday)
      return {
        status: "invalid",
        warning: rawWeekday
          ? `每周航班计划第${excelRow}行星期“${rawWeekday}”无效，现有计划保留`
          : `每周航班计划第${excelRow}行没有填写星期，现有计划保留`,
      };
    if (seenWeekdays.has(weekday))
      return {
        status: "invalid",
        warning: `每周航班计划第${excelRow}行星期“${rawWeekday}”重复，现有计划保留`,
      };
    seenWeekdays.add(weekday);
    plans = replaceWeeklyFlightPlan(
      plans,
      weekday as WeeklyFlightPlanEntry["weekday"],
      splitList(row[flightIndex])
    );
  }
  if (seenWeekdays.size !== 7) {
    const missing = Array.from({ length: 7 }, (_, index) => index + 1)
      .filter((weekday) => !seenWeekdays.has(weekday))
      .map((weekday) =>
        weekdayLabel(weekday as WeeklyFlightPlanEntry["weekday"])
      );
    return {
      status: "invalid",
      warning: `每周航班计划缺少${missing.join("、")}，现有计划保留`,
    };
  }
  return { status: "valid", plans };
}

function parseFatigueMap(workbook: XLSX.WorkBook): Map<string, number> {
  const sheetName = findSheet(workbook, ["岗位疲劳度", "疲劳度计算"]);
  const result = new Map<string, number>();
  if (!sheetName) return result;
  const data = rows(workbook, sheetName);
  let currentFlight = "";
  for (const row of data.slice(1)) {
    currentFlight = normalizeText(row[1]).toUpperCase() || currentFlight;
    const position = normalizePosition(row[5]);
    const points = Number(row[7]);
    if (currentFlight && position && Number.isFinite(points))
      result.set(`${currentFlight}|${position}`, points);
  }
  return result;
}

function parsePositions(
  workbook: XLSX.WorkBook,
  restoreErrors: string[]
): PositionRule[] | undefined {
  const sheetName = findSheet(workbook, ["岗位配置"]);
  if (!sheetName) return undefined;
  const fatigueMap = parseFatigueMap(workbook);
  const data = rows(workbook, sheetName);
  const header = data[0] ?? [];
  const flightIndex = headerIndex(header, ["航班号"], 0);
  const categoryIndex = headerIndex(header, ["项目分类", "分类"], 1);
  const nameIndex = headerIndex(header, ["岗位名称"], 2);
  const remarkIndex = headerIndex(header, ["备注"], 3);
  const qualifiedIndex = headerIndex(header, ["可胜任人员"], 4);
  const fatiguePointsIndex = headerIndex(header, ["疲劳点数"], 5);
  const minPassengersIndex = headerIndex(
    header,
    ["启用旅客人数", "最少旅客人数", "运力阈值"],
    fatiguePointsIndex + 1
  );
  const earlyReleaseIndex = headerIndex(
    header,
    ["提前撤岗分钟", "提前撤岗", "分流分钟"],
    minPassengersIndex + 1
  );
  const manualIndex = header.findIndex((value) =>
    normalizeText(value).includes("是否手动输入")
  );
  const result: PositionRule[] = [];
  let currentFlight = "";
  for (const [rowIndex, row] of data.slice(1).entries()) {
    if (row.every((value) => !normalizeText(value))) continue;
    currentFlight =
      normalizeText(row[flightIndex]).toUpperCase() || currentFlight;
    const name = normalizePosition(row[nameIndex]);
    if (!currentFlight || !name) {
      restoreErrors.push(
        `岗位配置第${rowIndex + 2}行：缺少航班号或岗位名称，不能完整恢复`
      );
      continue;
    }
    const rawQualified = normalizeText(row[qualifiedIndex]);
    const categoryText = normalizeText(row[categoryIndex]);
    if (categoryText.includes("支援") && !categoryText.includes("行政支援")) {
      restoreErrors.push(
        `岗位配置第${rowIndex + 2}行：包含已停用的岗位分类，不能完整恢复`
      );
      continue;
    }
    if (
      normalizeText(row[fatiguePointsIndex]) === "" ||
      !Number.isFinite(Number(row[fatiguePointsIndex])) ||
      Number(row[fatiguePointsIndex]) < 0
    )
      restoreErrors.push(
        `岗位配置第${rowIndex + 2}行：疲劳点数无效，不能完整恢复`
      );
    const supervisorFill = categoryText.includes("督导补位");
    const category: PositionRule["category"] = supervisorFill
      ? "常规"
      : categoryText.includes("机动督导")
        ? "机动督导"
        : categoryText.includes("行政支援")
          ? "行政支援"
          : categoryText.includes("引导")
            ? "引导"
            : categoryText.includes("分流")
              ? "分流"
              : "常规";
    result.push({
      id: createId("position"),
      flightNo: currentFlight,
      name,
      category,
      coverageRole: supervisorFill ? "supervisor-fill" : "none",
      remark: normalizeText(row[remarkIndex]),
      qualifiedStaffIds: rawQualified.includes("手动输入")
        ? []
        : splitList(rawQualified),
      manual:
        manualIndex >= 0
          ? ["是", "true", "1"].includes(normalizeText(row[manualIndex]))
          : rawQualified.includes("手动输入"),
      fatiguePoints:
        fatigueMap.get(`${currentFlight}|${name}`) ??
        (normalizeText(row[fatiguePointsIndex]) !== "" &&
        Number.isFinite(Number(row[fatiguePointsIndex]))
          ? Number(row[fatiguePointsIndex])
          : 1),
      minPassengers: Number(row[minPassengersIndex]) || 0,
      earlyReleaseMinutes: Number(row[earlyReleaseIndex]) || 0,
    });
  }
  const unique = new Map(
    result.map((rule) => [
      `${rule.flightNo}|${rule.name}|${rule.category}`,
      rule,
    ])
  );
  if (unique.size !== result.length)
    restoreErrors.push("岗位配置存在重复岗位，不能完整恢复");
  return orderPositionRules([...unique.values()]);
}

function staffIdByName(staff: Staff[], name: string): string {
  return staff.find((person) => person.name === name)?.id ?? "";
}

function parseHistory(
  workbook: XLSX.WorkBook,
  staff: Staff[]
): HistoryRecord[] | undefined {
  const sheetName = findSheet(workbook, ["历史排班", "排班结果"]);
  if (!sheetName) return undefined;
  const data = rows(workbook, sheetName);
  const header = data[0] ?? [];
  const idIndex = headerIndex(header, ["记录ID", "历史记录ID"], -1);
  const dateIndex = headerIndex(header, ["日期"], 0);
  const flightIndex = headerIndex(header, ["航班号"], -1);
  const positionIndex = headerIndex(header, ["岗位"], 1);
  const staffIdIndex = headerIndex(header, ["人员编号", "编号"], -1);
  const nameIndex = headerIndex(header, ["姓名"], 2);
  const startIndex = headerIndex(header, ["开始时间"], -1);
  const endIndex = headerIndex(header, ["结束时间"], -1);
  const flightCutoffIndex = headerIndex(header, ["航班截载时间"], -1);
  const hoursIndex = headerIndex(header, ["工作时长"], 3);
  const fatigueIndex = headerIndex(header, ["疲劳点"], -1);
  const remarkIndex = headerIndex(header, ["备注"], 4);
  const coverageIndex = headerIndex(header, ["历史覆盖范围"], -1);
  const gapFillIndex = headerIndex(header, ["分队长补差"], -1);
  const evidenceIndex = headerIndex(header, ["人工调整证据"], -1);
  const attendanceIndex = headerIndex(header, ["出勤时段"], -1);
  return data.slice(1).flatMap((row) => {
    const date = normalizeText(row[dateIndex]).slice(0, 10);
    const staffName = normalizeText(row[nameIndex]);
    let attendanceIntervals: HistoryRecord["attendanceIntervals"];
    try {
      attendanceIntervals = normalizeAttendanceIntervals(
        JSON.parse(
          attendanceIndex >= 0
            ? normalizeText(row[attendanceIndex]) || "null"
            : "null"
        )
      );
    } catch {
      /* Optional attendance metadata must not discard the load record. */
    }
    const position = normalizePosition(row[positionIndex]);
    const evidence = parseManualCountEvidence(
      evidenceIndex >= 0 ? normalizeText(row[evidenceIndex]) : ""
    );
    if (!date || (!staffName && !evidence.countBaseline?.staffId) || !position)
      return [];
    const importedStaffId =
      staffIdIndex >= 0 ? normalizeText(row[staffIdIndex]) : "";
    const startTime =
      startIndex >= 0 ? normalizeTime(normalizeText(row[startIndex])) : "";
    const endTime =
      endIndex >= 0 ? normalizeTime(normalizeText(row[endIndex])) : "";
    const flightCutoffTime =
      flightCutoffIndex >= 0
        ? normalizeTime(normalizeText(row[flightCutoffIndex]))
        : "";
    const rawHours = row[hoursIndex];
    const parsedHours = Number(rawHours);
    const hours =
      normalizeText(rawHours) !== "" && Number.isFinite(parsedHours)
        ? parsedHours
        : durationHours(startTime, endTime);
    const rawFatigue = fatigueIndex >= 0 ? row[fatigueIndex] : "";
    const parsedFatigue = Number(rawFatigue);
    const historyCoverage =
      coverageIndex >= 0 &&
      (normalizeText(row[coverageIndex]) === "complete" ||
        normalizeText(row[coverageIndex]) === "late-priority-only")
        ? (normalizeText(
            row[coverageIndex]
          ) as HistoryRecord["historyCoverage"])
        : undefined;
    const teamLeaderGapFill =
      gapFillIndex >= 0 &&
      ["是", "true", "1"].includes(
        normalizeText(row[gapFillIndex]).toLowerCase()
      )
        ? true
        : undefined;
    return [
      {
        id:
          (idIndex >= 0 && normalizeText(row[idIndex])) || createId("history"),
        date,
        flightNo:
          flightIndex >= 0 ? normalizeText(row[flightIndex]).toUpperCase() : "",
        position,
        staffId: importedStaffId || staffIdByName(staff, staffName),
        staffName,
        startTime,
        endTime,
        ...(flightCutoffTime ? { flightCutoffTime } : {}),
        ...(attendanceIntervals ? { attendanceIntervals } : {}),
        workHours: hours,
        fatiguePoints:
          normalizeText(rawFatigue) !== "" && Number.isFinite(parsedFatigue)
            ? parsedFatigue
            : hours,
        remark: normalizeText(row[remarkIndex]),
        ...(historyCoverage ? { historyCoverage } : {}),
        ...(teamLeaderGapFill ? { teamLeaderGapFill } : {}),
        ...evidence,
      },
    ];
  });
}

export function parseWorkbook(
  workbook: XLSX.WorkBook,
  currentStaff: Staff[],
  options: WorkbookImportOptions = {}
): WorkbookImport {
  const configurationRestoreErrors: string[] = [];
  const parsedLeaveTypes = parseLeaveTypes(workbook);
  const staffWarnings: string[] = [];
  const staff = parseStaff(
    workbook,
    parsedLeaveTypes.types ?? options.leaveTypes ?? [],
    staffWarnings,
    configurationRestoreErrors
  );
  const effectiveStaff = staff !== undefined ? staff : currentStaff;
  const flightConfigurationErrors: string[] = [];
  const flights = parseFlights(workbook, flightConfigurationErrors);
  const templates = parseTemplates(workbook, flightConfigurationErrors);
  const weeklyFlightPlanImport = parseWeeklyFlightPlans(workbook);
  const weeklyFlightPlans =
    weeklyFlightPlanImport?.status === "valid"
      ? weeklyFlightPlanImport.plans
      : undefined;
  const positionRules = parsePositions(workbook, configurationRestoreErrors);
  const history = parseHistory(workbook, effectiveStaff);
  const parsedRules = parseScheduleRuleSettings(workbook, effectiveStaff);
  if (
    positionRules &&
    parsedRules.settings?.mobileSupervisorFillRules !== undefined
  )
    migrateLegacySupervisorFillConfiguration(
      positionRules,
      parsedRules.settings.mobileSupervisorFillRules
    );
  const latePriorityFrequencyAdjustments =
    parseLatePriorityFrequencyAdjustments(workbook, configurationRestoreErrors);
  const ordinaryPriorityFrequencyAdjustments =
    parseOrdinaryPriorityFrequencyAdjustments(
      workbook,
      configurationRestoreErrors
    );
  const ordinaryPriorityPositions = parseOrdinaryPriorityPositions(workbook);
  const dutyRoster = parseDutyRosterOverrides(workbook, effectiveStaff);
  const halfRest = parseHalfRestSelections(workbook);
  const flightPlanConfirmations = parseFlightPlanConfirmations(workbook);
  const flightSeasonOverrides = parseFlightSeasonOverrides(workbook);
  if (ordinaryPriorityPositions.present) {
    parsedRules.settings = {
      ...(parsedRules.settings ?? {}),
      ordinaryPriorityPositions: ordinaryPriorityPositions.value,
    };
  }
  const warnings = [
    ...flightConfigurationErrors,
    ...halfRest.warnings,
    ...flightPlanConfirmations.warnings,
    ...flightSeasonOverrides.warnings,
    ...parsedRules.warnings,
    ...dutyRoster.warnings,
    ...parsedLeaveTypes.warnings,
    ...staffWarnings,
  ];
  // Older/partial parameter tables can supply defaults for ordinary import.
  // Complete restore must prove every parameter was actually in the file.
  const parameterRows = workbook.Sheets["规则参数"]
    ? rows(workbook, "规则参数")
    : [];
  const parameterCodeIndex = headerIndex(
    parameterRows[0] ?? [],
    ["参数代码"],
    0
  );
  const parameterCodes = new Set(
    parameterRows.slice(1).map((row) => normalizeText(row[parameterCodeIndex]))
  );
  configurationRestoreErrors.push(
    ...SCHEDULE_SETTING_DEFINITIONS.filter(
      (definition) =>
        !parameterCodes.has(definition.key) &&
        !OPTIONAL_CONFIGURATION_SCALARS.has(definition.key)
    ).map((definition) => `完整恢复缺少规则参数：${definition.label}`)
  );
  if (weeklyFlightPlanImport?.status === "invalid")
    warnings.push(weeklyFlightPlanImport.warning);
  const hasStandardSheet = Boolean(
    workbook.Sheets["航班换季确认"] ||
    workbook.Sheets["半休选择"] ||
    workbook.SheetNames.some((name) => name.includes("休假类别")) ||
    staff ||
    flights ||
    templates ||
    weeklyFlightPlanImport ||
    positionRules ||
    history ||
    parsedRules.recognized ||
    latePriorityFrequencyAdjustments !== undefined ||
    ordinaryPriorityFrequencyAdjustments !== undefined ||
    ordinaryPriorityPositions.present ||
    workbook.SheetNames.some((name) => name.includes("值班轮值"))
  );
  const legacySchedule = hasStandardSheet
    ? undefined
    : parseLegacyScheduleWorkbook(workbook, effectiveStaff, {
        year: new Date().getFullYear(),
        ...options.legacySchedule,
      });
  if (legacySchedule?.recognizedSheets)
    warnings.push(
      `识别到旧版横向排班：${legacySchedule.recognizedSheets} 个工作日、${legacySchedule.readyRecords} 条可导入、${legacySchedule.reviewRecords} 条待确认`
    );
  if (
    staff?.length === 0 &&
    sheetHasDataRows(workbook, ["人员信息", "员工信息"])
  )
    warnings.push("人员信息工作表没有有效数据");
  if (
    flights?.length === 0 &&
    sheetHasDataRows(workbook, ["航班计划"], ["每周航班计划"])
  )
    warnings.push("航班计划工作表没有有效数据");
  if (
    templates?.length === 0 &&
    sheetHasDataRows(workbook, ["航班配置", "航班模板"])
  )
    warnings.push("航班配置工作表没有有效数据");
  if (positionRules?.length === 0 && sheetHasDataRows(workbook, ["岗位配置"]))
    warnings.push("岗位配置工作表没有有效数据");
  if (
    !workbook.Sheets["航班换季确认"] &&
    !workbook.Sheets["本季航班状态"] &&
    !staff &&
    !workbook.SheetNames.some((name) => name.includes("休假类别")) &&
    !flights &&
    !templates &&
    !weeklyFlightPlanImport &&
    !positionRules &&
    !history &&
    !parsedRules.recognized &&
    latePriorityFrequencyAdjustments === undefined &&
    ordinaryPriorityFrequencyAdjustments === undefined &&
    !ordinaryPriorityPositions.present &&
    !workbook.SheetNames.some((name) => name.includes("值班轮值")) &&
    !legacySchedule?.recognizedSheets
  )
    warnings.push("未识别到受支持的工作表");
  return {
    leaveTypes: parsedLeaveTypes.types,
    flightSeasonOverrides: flightSeasonOverrides.value,
    staff,
    flights,
    templates,
    flightConfigurationErrors,
    configurationRestoreErrors,
    weeklyFlightPlans,
    ...(weeklyFlightPlanImport
      ? { weeklyFlightPlanStatus: weeklyFlightPlanImport.status }
      : {}),
    positionRules,
    history,
    legacySchedule,
    settings: parsedRules.settings,
    latePriorityFrequencyAdjustments,
    ordinaryPriorityFrequencyAdjustments,
    dutyRosterOverrides: dutyRoster.value,
    halfRestSelections: halfRest.value,
    flightPlanConfirmations: flightPlanConfirmations.value,
    dutyRosterInvalid: dutyRoster.warnings.length > 0,
    warnings,
  };
}

export async function importWorkbook(
  file: File,
  currentStaff: Staff[],
  options: WorkbookImportOptions = {}
): Promise<WorkbookImport> {
  const workbook = XLSX.read(await file.arrayBuffer(), {
    type: "array",
    cellDates: false,
  });
  return parseWorkbook(workbook, currentStaff, options);
}

